<?php $rows=$pdo->query("SELECT s.tanggal,mk.nama_mk,d.nama dosen,k.nama_kelas,COUNT(km.mahasiswa_id) total,COALESCE(SUM(a.status IN ('Hadir','Terlambat')),0) hadir FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN dosen d ON d.id=j.dosen_id JOIN kelas k ON k.id=j.kelas_id JOIN kelas_mahasiswa km ON km.kelas_id=k.id LEFT JOIN absensi a ON a.sesi_id=s.id AND a.mahasiswa_id=km.mahasiswa_id GROUP BY s.id ORDER BY s.tanggal DESC")->fetchAll();?><section class="section"><table class="table"><thead><tr><th>Tanggal</th><th>Mata Kuliah</th><th>Dosen</th><th>Kelas</th><th>Hadir</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['nama_mk'])?></td><td><?=e($r['dosen'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=$r['hadir']?></td><td><?=$r['total']?></td></tr><?php endforeach;?></tbody></table></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>